<script setup lang="ts">
import { FileSignature, Plus, Save, RefreshCw, Download, ShieldCheck, FileText } from '@lucide/vue';
import PartnerLegalEntitiesPage from './PartnerLegalEntitiesPage.vue';

type Template = { id: string; templateKey: string; version: number; documentType: string; title: string; bodyHtml: string; audience: string; taxStatus: string; entityType: string; isActive: boolean };
const config = useRuntimeConfig();
const { token } = useWorkspaceSession();
const section = ref('templates');
const busy = ref(false), loading = ref(false), error = ref(''), notice = ref('');
const workspace = ref<any>(null);
const participants = ref<any[]>([]), search = ref('');
const selectedParticipant = ref(''), entityId = ref('');
const generated = ref<any[]>([]);
const editing = ref<any>(null);
const settings = reactive({ pepEnabled: false, providerKey: 'SMS_AERO', codeTtlSeconds: 300, maxAttempts: 5, resendCooldownSeconds: 60, consentRequired: true, eligibleDocumentTypes: ['SERVICE_AGREEMENT', 'REWARD_SCHEDULE', 'SERVICE_ACT', 'PAYOUT_REQUEST'] as string[] });
const labels: Record<string,string> = { PEP_CONSENT: 'Согласие на ПЭП', SERVICE_AGREEMENT: 'Договор услуг', REWARD_SCHEDULE: 'Задание и вознаграждение', SERVICE_ACT: 'Акт услуг', PAYOUT_REQUEST: 'Заявление на выплату' };
const tokens = [
  { key: 'partner_name', label: 'ФИО партнёра' }, { key: 'partner_inn', label: 'ИНН партнёра' },
  { key: 'partner_address', label: 'Адрес партнёра' }, { key: 'program_kind', label: 'Название программы' },
  { key: 'company_name', label: 'Название нашей компании' }, { key: 'company_inn', label: 'ИНН нашей компании' },
  { key: 'company_address', label: 'Адрес нашей компании' }, { key: 'reward_terms', label: 'Условия вознаграждения' },
  { key: 'period_start', label: 'Начало периода' }, { key: 'period_end', label: 'Конец периода' },
  { key: 'document_number', label: 'Номер документа' }, { key: 'reward_amount', label: 'Начислено за период' },
  { key: 'payout_amount', label: 'Сумма к выплате' },
];
const tokenLabel = (name: string) => `{{${name}}}`;
const bodyEditor = ref<HTMLTextAreaElement | null>(null);
function htmlToText(html = '') { return html.replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/(p|h[1-6]|li)>/gi, '\n').replace(/<li[^>]*>/gi, '• ').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim(); }
function textToHtml(text = '') { return text.split(/\n\s*\n/).map(paragraph => `<p>${paragraph.trim().split('\n').map(line => line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')).join('<br>')}</p>`).join(''); }
function insertToken(key: string) { const el = bodyEditor.value; const text = editing.value?.bodyText || ''; const start = el?.selectionStart ?? text.length; const end = el?.selectionEnd ?? text.length; const value = `{{${key}}}`; editing.value.bodyText = `${text.slice(0, start)}${value}${text.slice(end)}`; nextTick(() => { el?.focus(); el?.setSelectionRange(start + value.length, start + value.length); }); }
const previewText = computed(() => (editing.value?.bodyText || '').replace(/{{\s*([a-z_]+)\s*}}/gi, (_: string, key: string) => ({ partner_name: 'Анна Иванова', partner_inn: 'ИНН партнёра', partner_address: 'Адрес партнёра', program_kind: 'Реферальная программа', company_name: 'ООО «Саркисян»', company_inn: 'ИНН компании', company_address: 'Адрес компании', reward_terms: '7% от подтверждённых покупок', period_start: '01.10.2026', period_end: '31.10.2026', document_number: 'P-0001', reward_amount: '5 000 ₽', payout_amount: '5 000 ₽' } as Record<string,string>)[key] || `[${key}]`));
const documentTypes = Object.keys(labels);
function api(path: string, options: any = {}) { return $fetch<any>(`/partners/admin/documents${path}`, { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${token.value}` }, timeout: 30000, ...options }); }
async function load() { loading.value = true; error.value = ''; try { workspace.value = await api('/workspace'); Object.assign(settings, workspace.value.settings); await loadParticipants(); } catch (e: any) { error.value = e?.data?.message || 'Не удалось загрузить настройки документов'; } finally { loading.value = false; } }
async function loadParticipants() { participants.value = await api(`/participants${search.value ? `?search=${encodeURIComponent(search.value)}` : ''}`); }
function blankTemplate() { return { templateKey: '', documentType: 'SERVICE_AGREEMENT', title: 'Договор оказания информационных услуг', bodyText: 'ДОГОВОР ОКАЗАНИЯ ИНФОРМАЦИОННЫХ УСЛУГ\n\nЗаказчик: {{company_name}}, ИНН {{company_inn}}, адрес: {{company_address}}.\nИсполнитель: {{partner_name}}, ИНН {{partner_inn}}, адрес: {{partner_address}}.\n\nПрограмма: {{program_kind}}.\nУсловия вознаграждения: {{reward_terms}}.\nПериод: {{period_start}} — {{period_end}}.\nНомер документа: {{document_number}}.', audience: 'ALL', taxStatus: 'ALL', entityType: 'ALL', isActive: false } as Partial<Template> & { templateKey: string; bodyText: string } }
function editTemplate(row?: Template) { editing.value = row ? { ...row, bodyText: htmlToText(row.bodyHtml), isActive: false } : blankTemplate(); }
async function saveTemplate() { if (busy.value || !editing.value) return; busy.value = true; error.value = ''; try { const body = { ...editing.value, bodyHtml: textToHtml(editing.value.bodyText) }; delete body.id; delete body.version; delete body.bodyText; await api('/templates', { method: 'POST', body }); editing.value = null; notice.value = 'Сохранена новая версия шаблона'; await load(); } catch (e: any) { error.value = Array.isArray(e?.data?.message) ? e.data.message.join('; ') : e?.data?.message || 'Не удалось сохранить шаблон'; } finally { busy.value = false; } }
async function activateTemplate(row: Template) { busy.value = true; error.value = ''; try { await api(`/templates/${row.id}/activate`, { method: 'POST' }); notice.value = `Активирована версия ${row.version}`; await load(); } catch (e: any) { error.value = e?.data?.message || 'Не удалось активировать шаблон'; } finally { busy.value = false; } }
async function saveSettings() { busy.value = true; error.value = ''; try { const result = await api('/settings', { method: 'PATCH', body: { ...settings, pepEnabled: false } }); Object.assign(settings, result); notice.value = 'Настройки SMS-ПЭП сохранены. Подписание останется выключенным до запуска полного процесса.'; await load(); } catch (e: any) { error.value = e?.data?.message || 'Не удалось сохранить настройки'; } finally { busy.value = false; } }
async function generate() { if (!selectedParticipant.value || !entityId.value || busy.value) return; busy.value = true; error.value = ''; generated.value = []; try { generated.value = await api('/generate', { method: 'POST', body: { participantId: selectedParticipant.value, entityId: entityId.value } }); notice.value = `Сформировано документов: ${generated.value.length}`; } catch (e: any) { error.value = e?.data?.message || 'Не удалось сформировать документы'; } finally { busy.value = false; } }
async function download(row: any) { const response = await fetch(`${config.public.apiBase}/partners/admin/documents/download/${row.id}`, { headers: { Authorization: `Bearer ${token.value}` } }); if (!response.ok) { error.value = 'Не удалось скачать документ'; return; } const blob = await response.blob(); const href = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = href; a.download = row.fileName; a.click(); URL.revokeObjectURL(href); }
onMounted(load);
</script>

<template>
  <section class="partner-workspace crm-standard partner-doc-settings">
    <header class="crm-page-header"><div><h1>Документы партнёров</h1><p>Общие настройки для блогеров и клиентов реферальной программы: реквизиты, формы документов, генерация и SMS-ПЭП.</p></div><button class="crm-button" :disabled="loading" @click="load"><RefreshCw :size="17"/> Обновить</button></header>
    <p v-if="error" class="partner-feedback" role="alert">{{ error }}</p><p v-if="notice" class="partner-feedback" role="status">{{ notice }}</p>
    <nav class="pds-tabs" aria-label="Разделы документов"><button v-for="tab in [{id:'templates',label:'Шаблоны'}, {id:'generator',label:'Генератор'}, {id:'signature',label:'SMS-подпись'}, {id:'entities',label:'Реквизиты'}]" :key="tab.id" :class="{active:section===tab.id}" @click="section=tab.id">{{tab.label}}</button></nav>

    <div v-if="section==='entities'"><PartnerLegalEntitiesPage/></div>
    <section v-else-if="section==='templates'" class="pds-section">
      <header class="pds-heading"><div><h2>Шаблоны документов</h2><p>Каждое сохранение создаёт новую версию. Генератор использует только активную подходящую версию.</p></div><button class="crm-button crm-button--primary" @click="editTemplate()"><Plus :size="17"/> Добавить шаблон</button></header>
      <div class="pds-start-help"><FileText :size="20"/><div><strong>Что здесь делать</strong><p>Мы уже добавили стартовые формы. Нажмите «Создать версию», чтобы посмотреть или изменить текст. Пишите обычным текстом — HTML знать не нужно. Переменные вставляйте кнопками ниже; при генерации они заменятся данными партнёра и компании.</p></div></div>
      <div v-if="editing" class="pds-editor crm-surface"><header class="pds-editor-intro"><span class="pds-step">Редактор шаблона</span><h3>{{editing.id ? 'Создать новую версию' : 'Добавить свой шаблон'}}</h3><p>Заполните поля и сохраните. Новая версия сохранится отдельно, прежний документ останется без изменений.</p></header><form class="pds-form" @submit.prevent="saveTemplate">
        <label>1. Какой документ создаём?<select v-model="editing.documentType" class="crm-input"><option v-for="type in documentTypes" :key="type" :value="type">{{labels[type]}}</option></select><small>Тип документа помогает генератору выбрать нужную форму.</small></label>
        <label>Название документа<input v-model="editing.title" class="crm-input" required maxlength="240" placeholder="Например: Договор оказания информационных услуг"/><small>Это название будет в списке и в скачанном файле.</small></label>
        <label>Для кого эта версия?<select v-model="editing.audience" class="crm-input"><option value="ALL">Для всех партнёров</option><option value="BLOGGER">Только для блогеров</option><option value="REFERRAL">Только для реферальных клиентов</option></select><small>Оставьте «для всех», если текст договора одинаковый.</small></label>
        <label>Налоговый статус<select v-model="editing.taxStatus" class="crm-input"><option value="ALL">Любой статус</option><option value="SELF_EMPLOYED">Самозанятый</option><option value="INDIVIDUAL_ENTREPRENEUR">ИП</option></select><small>Выберите статус, если для него нужна отдельная форма.</small></label>
        <label>От чьего имени документ?<select v-model="editing.entityType" class="crm-input"><option value="ALL">От ИП или ООО</option><option value="IP">Только от ИП</option><option value="LLC">Только от ООО</option></select><small>Реквизиты выбранной стороны будут подставлены автоматически.</small></label>
        <div class="pds-wide pds-writing-guide"><strong>2. Напишите текст документа</strong><p>Нажмите на переменную, чтобы вставить её в место курсора. Не меняйте текст внутри фигурных скобок.</p><div class="pds-token-list"><button v-for="item in tokens" :key="item.key" type="button" class="pds-token" @click="insertToken(item.key)"><code>{{tokenLabel(item.key)}}</code><span>{{item.label}}</span></button></div></div>
        <label class="pds-wide">Текст документа<textarea ref="bodyEditor" v-model="editing.bodyText" class="crm-input pds-editor-text" rows="15" required maxlength="50000" placeholder="Напишите текст и добавьте нужные переменные кнопками выше."/><small>Можно вставить готовый текст из Word. Разделяйте абзацы пустой строкой.</small></label>
        <details class="pds-preview pds-wide"><summary>Посмотреть пример с подставленными данными</summary><pre>{{previewText}}</pre></details>
        <label class="pds-check pds-wide"><input v-model="editing.isActive" type="checkbox"/> Сделать эту версию активной для выбранного типа и аудитории</label>
        <footer class="pds-wide"><button class="crm-button crm-button--primary" :disabled="busy" type="submit"><Save :size="16"/> Сохранить новую версию</button><button class="crm-button" type="button" @click="editing=null">Закрыть</button></footer>
      </form></div>
      <div class="pds-table"><article v-for="item in workspace?.templates" :key="item.id" class="pds-template crm-surface"><div><span class="pds-kind"><FileText :size="15"/> {{labels[item.documentType] || item.documentType}}</span><h3>{{item.title}}</h3><p>Версия {{item.version}} · {{item.audience==='ALL'?'Все партнёры':item.audience==='BLOGGER'?'Блогеры':'Рефералы'}} · {{item.taxStatus==='ALL'?'любой статус':item.taxStatus==='SELF_EMPLOYED'?'самозанятый':'ИП'}} · {{item.entityType==='ALL'?'ИП/ООО':item.entityType}}</p><small>{{item.isActive?'Активный шаблон':'Архивная версия'}}</small></div><div class="pds-actions"><button class="crm-button" @click="editTemplate(item)">Создать версию</button><button v-if="!item.isActive" class="crm-button" :disabled="busy" @click="activateTemplate(item)">Активировать</button></div></article><p v-if="!workspace?.templates?.length" class="crm-surface pds-empty">Пока нет пользовательских шаблонов. Можно создать свои формы и активировать нужные версии.</p></div>
    </section>

    <section v-else-if="section==='generator'" class="pds-section"><header class="pds-heading"><div><h2>Генератор документов</h2><p>Выберите участника и реквизиты стороны договора. Для каждого типа будет взят подходящий активный шаблон.</p></div></header>
      <div class="pds-generator crm-surface"><label>Найти блогера или реферального клиента<input v-model="search" class="crm-input" placeholder="Имя, код или email" @input="loadParticipants"/><select v-model="selectedParticipant" class="crm-input" size="5"><option v-for="p in participants" :key="p.id" :value="p.id">{{p.displayName}} · {{p.kind==='BLOGGER'?'блогер':'реферал'}} · {{p.user.email}}</option></select></label><label>Реквизиты заказчика<select v-model="entityId" class="crm-input"><option value="" disabled>Выберите ИП или ООО</option><option v-for="entity in workspace?.entities?.filter((x:any)=>x.isActive)" :key="entity.id" :value="entity.id">{{entity.entityType==='IP'?'ИП':'ООО'}} · {{entity.legalName}}</option></select></label><button class="crm-button crm-button--primary" :disabled="busy||!selectedParticipant||!entityId" @click="generate"><FileSignature :size="17"/> Сформировать комплект</button></div>
      <div v-if="generated.length" class="pds-generated"><article v-for="doc in generated" :key="doc.id" class="pds-template crm-surface"><div><span class="pds-kind">{{labels[doc.documentType]}}</span><h3>{{doc.title}}</h3><p>{{doc.templateVersion}} · черновик</p></div><button class="crm-button" @click="download(doc)"><Download :size="16"/> Скачать DOC</button></article></div>
    </section>

    <section v-else class="pds-section"><header class="pds-heading"><div><h2>SMS-подпись и простая электронная подпись</h2><p>Здесь задаются правила отправки кода и какие документы могут подписываться таким способом.</p></div><ShieldCheck :size="27"/></header>
      <div class="pds-sms-status crm-surface"><strong>SMS Aero: {{workspace?.smsIntegration?.configured ? 'реквизиты интеграции заполнены' : 'интеграция не настроена'}}</strong><span> {{workspace?.smsIntegration?.isEnabled ? 'Интеграция включена' : 'Интеграция выключена'}} · SMS-ПЭП выключена</span><NuxtLink to="/crm/settings/integrations">Открыть интеграции CRM</NuxtLink></div>
      <form class="pds-settings crm-surface" @submit.prevent="saveSettings"><label>Провайдер<select v-model="settings.providerKey" class="crm-input"><option value="SMS_AERO">SMS Aero</option></select></label><label>Срок действия кода, секунд<input v-model.number="settings.codeTtlSeconds" class="crm-input" type="number" min="60" max="900"/></label><label>Максимум попыток ввода<input v-model.number="settings.maxAttempts" class="crm-input" type="number" min="3" max="10"/></label><label>Пауза между повторной отправкой, секунд<input v-model.number="settings.resendCooldownSeconds" class="crm-input" type="number" min="30" max="600"/></label><label class="pds-check"><input v-model="settings.consentRequired" type="checkbox"/> Требовать предварительное согласие на использование ПЭП</label><div class="pds-doc-checks"><strong>Документы, допустимые к подписанию кодом</strong><label v-for="type in documentTypes.filter(x=>x!=='PEP_CONSENT')" :key="type"><input v-model="settings.eligibleDocumentTypes" type="checkbox" :value="type"/> {{labels[type]}}</label></div><p class="pds-warning">Сейчас сохраняются параметры, но подписание остаётся выключенным: в CRM ещё нет полного процесса выдачи и проверки одноразового кода, журнала подписания и выдачи подписанного экземпляра. SMS-ключи задаются в защищённой карточке SMS Aero и сюда не копируются.</p><button class="crm-button crm-button--primary" :disabled="busy"><Save :size="16"/> Сохранить настройки</button></form>
    </section>
  </section>
</template>

<style scoped>
