nter}.pds-warning{grid-column:1/-1;padding:14px;border-left:3px solid #bb8648;background:#f6f2ed;margin:0}.pds-settings>button{justify-self:start}
.pds-start-help{display:flex;align-items:flex-start;gap:13px;padding:16px 18px;border:1px solid rgba(255,255,255,.16);border-radius:12px;background:rgba(255,255,255,.045)}.pds-start-help>svg{flex:none;opacity:.8}.pds-start-help p,.pds-editor-intro p{margin:5px 0 0;color:var(--crm-muted,#aaa);line-height:1.6}.pds-editor-intro{margin-bottom:22px}.pds-editor-intro h3{margin:7px 0 0}.pds-step{font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.7}.pds-writing-guide{display:grid;gap:8px;padding:16px;border-radius:10px;background:rgba(255,255,255,.045)}.pds-writing-guide p{margin:0;color:var(--crm-muted,#aaa)}.pds-token-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:8px}.partner-doc-settings .pds-token{display:flex;align-items:center;gap:10px;min-height:42px;padding:8px 10px!important;border:1px solid rgba(255,255,255,.18)!important;border-radius:8px!important;background:rgba(255,255,255,.055)!important;color:#f4f4f4!important;text-align:left!important}.partner-doc-settings .pds-token:hover{background:rgba(255,255,255,.12)!important}.pds-token code{flex:none;padding:4px 6px;border-radius:5px;background:rgba(255,255,255,.12);color:#fff;font-size:11px}.pds-token span{color:#ddd;font-size:12px}.pds-editor-text{font:14px/1.7 inherit!important;min-height:300px;white-space:pre-wrap}.pds-preview{border:1px solid rgba(255,255,255,.14);border-radius:9px;padding:12px 14px}.pds-preview summary{cursor:pointer;font-weight:600}.pds-preview pre{margin:12px 0 0;padding:14px;border-radius:8px;background:rgba(0,0,0,.2);color:#eee;white-space:pre-wrap;font:13px/1.7 inherit}
@media(max-width:850px){.pds-generator{grid-template-columns:1fr}.pds-form,.pds-settings{grid-template-columns:1fr}.pds-wide,.pds-warning{grid-column:auto}.pds-template{align-items:flex-start;flex-direction:column}.pds-sms-status a{margin-left:0}.pds-token-list{grid-template-columns:repeat(2,minmax(0,1fr))}}
